def task36d47b14_transform_v7(grid):
    """
    Transpose, horizontally mirror each row, but resolve 2s differently:

    For cursed positions (where T[i][j] == 2):
    1. First try T[i][23-j] (mirror within row)
    2. If failed (both are cursed), try input vertical mirror: input[23-i][j]
    """
    n = len(grid)
    transposed = [[grid[j][i] for j in range(n)] for i in range(n)]

    for i in range(n):
        for j in range(n):
            if transposed[i][j] == 2:
                mirror_pos = 23 - j
                if 0 <= mirror_pos < n:
                    transposed[i][j] = transposed[i][mirror_pos]

    # Second pass: replace remaining 2s with vertical mirror from input
    for i in range(n):
        for j in range(n):
            if transposed[i][j] == 2:
                transposed[i][j] = grid[23-i][j]

    return transposed

