def task36d47b14_transform_v8(grid):
    """Multiple passes until no 2s remain or no progress."""
    n = len(grid)
    transposed = [[grid[j][i] for j in range(n)] for i in range(n)]

    max_passes = 10
    for pass_num in range(max_passes):
        made_progress = False
        for i in range(n):
            for j in range(n):
                if transposed[i][j] == 2:
                    mirror_pos = 23 - j
                    if 0 <= mirror_pos < n and transposed[i][mirror_pos] != 2:
                        transposed[i][j] = transposed[i][mirror_pos]
                        made_progress = True
                    else:
                        # Use vertical mirror from input
                        v_over = 23 - i
                        if v_over >= 0 and v_over < n:
                            transposed[i][j] = grid[v_over][j]
                            made_progress = True
        if not made_progress:
            break

    return transposed

